#13
nt_count = {}
seq = ''

for nt in seq:
    if nt in nt_count:
        previous_count = nt_count[nt]
        new_count = previous_count + 1
        nt_count[nt] = new_count
    else:
    # se não, adicionamos e contamos 1
        nt_count[nt] = 1;

print(nt_count)
print(nt_count['G'])

nt_comp = {'A': nt_count['A'], 'G': nt_count['G'], 'C': nt_count['C'], 'T': nt_count['T']}

conteudoGC = nt_comp['G'] + nt_comp ['C']

print('O conteúdo de GC é: ', conteudoGC)

total = sum(nt_comp.values())

for nt, count in nt_comp.items():
    comp = count/total
    print(nt, comp)